def estimate_connectivity(n: int, c: float, trials: int, seed: int = 0) -> tuple[float, float]:
    rng = Random(seed); p = (log(n) + c) / n; connected = 0
    for _ in range(trials):
        graph = [set() for _ in range(n)]
        for u in range(n):
            for v in range(u + 1, n):
                if rng.random() < p:
                    graph[u].add(v); graph[v].add(u)
        seen = {0}; stack = [0]
        frontier = [0]; seen = {0}
        while frontier:
            u = frontier.pop()
            for v in graph[u]:
                if v not in seen: seen.add(v); frontier.append(v)
        connected += len(seen) == n
    return connected / trials, exp(-exp(-c))

